(function (window) {
  'use strict';

  var app = window.RussianCinemaPlugin = window.RussianCinemaPlugin || {};
  var pageCache = {};
  var genresByType = {};
  var genreRequests = {};

  function request(endpoint) {
    var path = endpoint.replace(/^\/+/, '');
    var customKey = '';
    if (Lampa.Storage) {
      if (Lampa.Storage.field) customKey = Lampa.Storage.field('russian_cinema_tmdb_key') || '';
      if (!customKey && Lampa.Storage.get) customKey = Lampa.Storage.get('russian_cinema_tmdb_key', '') || '';
    }
    var key = customKey || (Lampa.TMDB && Lampa.TMDB.key ? Lampa.TMDB.key() : '');
    if (!key) return Promise.reject(new Error('В этой версии Lampa недоступен встроенный ключ TMDB. Обновите приложение.'));
    var isAccessToken = key.indexOf('.') !== -1 || key.indexOf('eyJ') === 0;
    var url = Lampa.TMDB && Lampa.TMDB.api ? Lampa.TMDB.api(path) : 'https://api.themoviedb.org/3/' + path;
    if (!isAccessToken) url += (url.indexOf('?') === -1 ? '?' : '&') + 'api_key=' + encodeURIComponent(key);
    var network = Lampa.Reguest ? new Lampa.Reguest() : (Lampa.Network || null);

    if (network && network.silent) {
      return new Promise(function (resolve, reject) {
        network.silent(url, function (data) {
          if (data && data.success === false) {
            reject(new Error(data.status_message || 'TMDB отклонил запрос. Проверьте API Key.'));
          } else {
            resolve(data);
          }
        }, function (error, exception) {
          var statusCode = error && Number(error.status || (network.errorCode && network.errorCode(error))) || 0;
          var body = network.errorJSON ? network.errorJSON(error) : (error && error.responseJSON) || {};
          var decoded = network.errorDecode ? network.errorDecode(error, exception) : '';
          var detail = body.status_message || body.text || (error && (error.statusText || error.message)) || decoded || '';
          if (!statusCode) {
            var code = String(detail).match(/\b([45]\d\d)\b/);
            if (code) statusCode = Number(code[1]);
          }
          var message;

          if (statusCode === 401) {
            message = 'HTTP 401: TMDB отклонил ключ. Проверьте API Key v3 в настройках плагина.';
          } else if (statusCode === 403) {
            message = 'HTTP 403: доступ запрещён сервером или прокси.';
          } else if (statusCode === 404) {
            message = 'HTTP 404: адрес TMDB или прокси не найден. Проверьте настройки прокси TMDB в Lampa.';
          } else if (statusCode === 0) {
            message = 'Нет ответа от TMDB: проверьте VPN, сеть, DNS и прокси на телевизоре.';
          } else {
            message = 'Ошибка TMDB, HTTP ' + statusCode + '.';
          }

          if (detail) message += ' Ответ: ' + String(detail).replace(/\s+/g, ' ').slice(0, 180);
          reject(new Error(message));
        }, false, isAccessToken ? { headers: { Authorization: 'Bearer ' + key } } : undefined);
      });
    }

    var headers = { accept: 'application/json' };
    if (isAccessToken) headers.Authorization = 'Bearer ' + key;
    return fetch(url, { headers: headers }).then(function (response) {
      return response.json().then(function (data) {
        if (!response.ok) {
          if (response.status === 401) throw new Error('HTTP 401: TMDB отклонил ключ. Проверьте API Key v3 в настройках плагина.');
          throw new Error(data.status_message || 'TMDB вернул ошибку (' + response.status + ').');
        }
        return data;
      });
    });
  }

  function loadGenres(mediaType) {
    if (genresByType[mediaType]) return Promise.resolve(genresByType[mediaType]);
    if (genreRequests[mediaType]) return genreRequests[mediaType];
    genreRequests[mediaType] = request('/genre/' + mediaType + '/list?language=ru-RU').then(function (data) {
      genresByType[mediaType] = Array.isArray(data.genres) ? data.genres : [];
      return genresByType[mediaType];
    }).catch(function () {
      genresByType[mediaType] = [];
      return genresByType[mediaType];
    });
    return genreRequests[mediaType];
  }

  function getPage(mediaType, pageNumber, filters, force) {
    return loadGenres(mediaType).then(function (genres) {
      var genreIds = genres.filter(function (item) {
        return filters.genreNames.indexOf(item.name) >= 0;
      }).map(function (item) { return String(item.id); });
      var cacheKey = [mediaType, pageNumber, filters.strictStudios, filters.genreNames.slice().sort().join(','), filters.year, filters.minRating, filters.sort].join(':');
      var saved = pageCache[cacheKey];
      if (!force && saved && Date.now() - saved.time < 15 * 60 * 1000) return saved.value;

      var endpoint = mediaType === 'tv' ? '/discover/tv' : '/discover/movie';
      var mediaSort = filters.sort === 'date.desc' ? (mediaType === 'tv' ? 'first_air_date.desc' : 'primary_release_date.desc') : filters.sort;
      var params = 'page=' + pageNumber + '&language=ru-RU&include_adult=false&sort_by=' + encodeURIComponent(mediaSort) + '&with_origin_country=RU';
      if (genreIds.length) params += '&with_genres=' + encodeURIComponent(genreIds.join(','));
      if (filters.year) params += (mediaType === 'tv' ? '&first_air_date_year=' : '&primary_release_year=') + encodeURIComponent(filters.year);
      if (filters.minRating) params += '&vote_average.gte=' + encodeURIComponent(filters.minRating);

      return request(endpoint + '?' + params).then(function (data) {
        var candidates = Array.isArray(data.results) ? data.results : [];
        return mapInBatches(candidates, 4, function (candidate) {
          return request('/' + mediaType + '/' + candidate.id + '?language=ru-RU&append_to_response=images&include_image_language=ru,en,null').then(function (detail) {
            var studios = (detail.production_companies || []).filter(function (company) {
              return company.origin_country === 'RU';
            });
            if (filters.strictStudios && !studios.length) return null;
            var companies = filters.strictStudios ? studios : (detail.production_companies || []);
            var posterPaths = posterPathsFor(detail, candidate);
            detail.poster_path = posterPaths.shift() || null;
            detail.backdrop_path = detail.backdrop_path || candidate.backdrop_path || null;
            var normalized = normalize(detail, mediaType, companies);
            normalized.poster_fallbacks = posterPaths;
            return normalized;
          }).catch(function () { return null; });
        }).then(function (items) {
          var value = {
            items: items.filter(Boolean),
            hasMore: pageNumber < Number(data.total_pages || 0)
          };
          pageCache[cacheKey] = { time: Date.now(), value: value };
          return value;
        });
      });
    });
  }

  function posterPathsFor(detail, candidate) {
    var posters = detail.images && detail.images.posters ? detail.images.posters.slice() : [];
    posters.sort(function (a, b) {
      function languageRank(image) {
        if (image.iso_639_1 === 'ru') return 0;
        if (image.iso_639_1 === 'en') return 1;
        if (!image.iso_639_1) return 2;
        return 3;
      }
      var languageDifference = languageRank(a) - languageRank(b);
      if (languageDifference) return languageDifference;
      var ratingDifference = Number(b.vote_average || 0) - Number(a.vote_average || 0);
      if (ratingDifference) return ratingDifference;
      return Number(b.vote_count || 0) - Number(a.vote_count || 0);
    });

    var paths = [];
    function add(path) {
      if (path && paths.indexOf(path) === -1) paths.push(path);
    }

    add(detail.poster_path);
    add(candidate.poster_path);
    posters.forEach(function (poster) { add(poster.file_path); });
    add(candidate.backdrop_path);
    add(detail.backdrop_path);
    return paths;
  }

  function normalize(item, mediaType, companies) {
    var series = mediaType === 'tv';
    return {
      id: Number(item.id),
      source: 'tmdb',
      media_type: mediaType,
      title: series ? (item.name || item.original_name || '') : (item.title || item.original_title || ''),
      original_title: series ? (item.original_name || item.name || '') : (item.original_title || item.title || ''),
      name: series ? (item.name || item.original_name || '') : '',
      original_name: series ? (item.original_name || item.name || '') : '',
      overview: item.overview || '',
      poster_path: item.poster_path || null,
      backdrop_path: item.backdrop_path || null,
      release_date: item.release_date || '',
      first_air_date: item.first_air_date || '',
      vote_average: Number(item.vote_average) || 0,
      vote_count: Number(item.vote_count) || 0,
      genre_ids: Array.isArray(item.genres) ? item.genres.map(function (genre) { return genre.id; }) : [],
      genres: Array.isArray(item.genres) ? item.genres : [],
      origin_country: item.origin_country || [],
      production_companies: companies.map(function (company) {
        return { id: company.id, name: company.name, origin_country: company.origin_country };
      }),
      is_series: series
    };
  }

  function mapInBatches(items, size, mapper) {
    var output = [];
    var chain = Promise.resolve();
    for (var index = 0; index < items.length; index += size) {
      (function (batch) {
        chain = chain.then(function () {
          return Promise.all(batch.map(mapper)).then(function (results) { output.push.apply(output, results); });
        });
      })(items.slice(index, index + size));
    }
    return chain.then(function () { return output; });
  }

  app.api = {
    request: request,
    loadGenres: loadGenres,
    getGenres: function (mediaType) { return genresByType[mediaType] || []; },
    getPage: getPage
  };
})(window);

/* src/filters.js */
(function (window) {
  'use strict';

  var app = window.RussianCinemaPlugin = window.RussianCinemaPlugin || {};

  app.createFilters = function (api, keepInView, onChange) {
    var state = {
      genreNames: [],
      strictStudios: false,
      year: '',
      minRating: 0,
      sort: 'popularity.desc'
    };

    function createButton() {
      var count = state.genreNames.length + (state.year ? 1 : 0) + (state.minRating ? 1 : 0) +
        (state.sort !== 'popularity.desc' ? 1 : 0) + (state.strictStudios ? 1 : 0);
      var button = $('<div class="russian-cinema-filter selector"></div>')
        .text('Фильтры' + (count ? ' · ' + count : ''));
      button.on('hover:enter', open);
      return keepInView(button);
    }

    function open() {
      Promise.all([api.loadGenres('movie'), api.loadGenres('tv')]).then(function () {
        var options = [
          { title: 'Показать результаты', action: 'apply' },
          {
            title: 'Жанр',
            subtitle: state.genreNames.length ? state.genreNames.join(', ') : 'Любой',
            key: 'genres',
            items: buildGenreOptions()
          },
          {
            title: 'Год выпуска',
            subtitle: state.year || 'Любой',
            key: 'year',
            items: buildSingleOptions([{ title: 'Любой год', value: '' }].concat(yearOptions()), state.year)
          },
          {
            title: 'Рейтинг',
            subtitle: state.minRating ? 'От ' + state.minRating.toFixed(1) : 'Любой',
            key: 'rating',
            items: buildSingleOptions([
              { title: 'Любой рейтинг', value: 0 },
              { title: 'От 5.0', value: 5 },
              { title: 'От 6.0', value: 6 },
              { title: 'От 7.0', value: 7 },
              { title: 'От 8.0', value: 8 }
            ], state.minRating)
          },
          {
            title: 'Сортировка',
            subtitle: sortLabel(state.sort),
            key: 'sort',
            items: buildSingleOptions([
              { title: 'По популярности', value: 'popularity.desc' },
              { title: 'По рейтингу', value: 'vote_average.desc' },
              { title: 'Сначала новые', value: 'date.desc' }
            ], state.sort)
          },
          {
            title: 'Производство',
            subtitle: state.strictStudios ? 'Российские студии' : 'Страна: Россия',
            key: 'production',
            items: buildSingleOptions([
              { title: 'Страна производства: Россия', value: false },
              { title: 'Российские студии', value: true }
            ], state.strictStudios)
          },
          { title: 'Сбросить фильтры', action: 'reset' }
        ];

        Lampa.Select.show({
          title: Lampa.Lang && Lampa.Lang.translate ? Lampa.Lang.translate('title_filter') : 'Фильтр',
          items: options,
          onBack: function () {
            onChange();
            Lampa.Controller.toggle('content');
          },
          onSelect: function (item) {
            if (item.action === 'apply') {
              Lampa.Controller.toggle('content');
              onChange('apply');
            } else if (item.action === 'reset') {
              reset();
              onChange('reset');
              open();
            } else {
              showSubmenu(item);
            }
          }
        });
      });
    }

    function showSubmenu(menu) {
      var options = menu.items;
      var multi = menu.key === 'genres';
      Lampa.Select.show({
        title: menu.title,
        items: options,
        onBack: function () {
          onChange();
          open();
        },
        onCheck: function () {
          state.genreNames = options.filter(function (item) { return item.checked; }).map(function (item) { return item.value; });
        },
        onSelect: function (item) {
          if (multi) return;
          if (menu.key === 'year') state.year = item.value;
          if (menu.key === 'rating') state.minRating = item.value;
          if (menu.key === 'sort') state.sort = item.value;
          if (menu.key === 'production') state.strictStudios = item.value;
          onChange();
          open();
        }
      });
    }

    function reset() {
      state.genreNames = [];
      state.year = '';
      state.minRating = 0;
      state.sort = 'popularity.desc';
      state.strictStudios = false;
    }

    function buildGenreOptions() {
      var genres = [];
      var names = {};
      ['movie', 'tv'].forEach(function (mediaType) {
        api.getGenres(mediaType).forEach(function (item) {
          if (!names[item.name]) {
            names[item.name] = true;
            genres.push({ title: item.name, value: item.name, checkbox: true, checked: state.genreNames.indexOf(item.name) >= 0 });
          }
        });
      });
      return genres;
    }

    function yearOptions() {
      var items = [];
      for (var value = new Date().getFullYear(); value >= 1950; value -= 1) {
        items.push({ title: String(value), value: String(value) });
      }
      return items;
    }

    function buildSingleOptions(items, selected) {
      items.forEach(function (item) { item.selected = item.value === selected; });
      return items;
    }

    function sortLabel(value) {
      if (value === 'vote_average.desc') return 'По рейтингу';
      if (value === 'date.desc') return 'Сначала новые';
      return 'По популярности';
    }

    return {
      state: state,
      createButton: createButton,
      open: open
    };
  };
})(window);

/* src/navigation.js */
(function (window) {
  'use strict';

  var app = window.RussianCinemaPlugin = window.RussianCinemaPlugin || {};

  app.createNavigation = function (options) {
    var activeRow = 0;

    function rows() {
      return options.rows();
    }

    function set(index) {
      activeRow = Math.max(0, Math.min(index, rows().length - 1));
      return activeRow;
    }

    function move(direction) {
      var next = activeRow + direction;
      if (next < 0) {
        activeRow = 0;
        options.onHead();
        return;
      }
      if (next >= rows().length) return;

      activeRow = next;
      options.update();
      options.scrollTo(rows()[activeRow]);
    }

    return {
      current: function () { return activeRow; },
      row: function () { return rows()[activeRow]; },
      set: set,
      move: move
    };
  };
})(window);

/* src/catalog.js */
(function (window) {
  'use strict';

  var app = window.RussianCinemaPlugin = window.RussianCinemaPlugin || {};

  app.RussianCinemaView = function () {
    var self = this;
    var api = app.api;
    var pageScroll = new Lampa.Scroll({ mask: true, over: true, scroll_by_item: true, end_ratio: 2 });
    var root = $('<div class="russian-cinema-page"></div>');
    var controls = $('<div class="russian-cinema-controls"></div>');
    var movies = createRail('movie', 'Фильмы');
    var series = createRail('tv', 'Сериалы');
    var pageLimit = 4;
    var pageFillTarget = 12;
    var destroyed = false;
    var lastFocus = null;
    var navigation = app.createNavigation({
      rows: function () { return [null, movies, series]; },
      update: updateCollection,
      scrollTo: function (row) { pageScroll.update(row ? row.section[0] : controls[0]); },
      onHead: function () { Lampa.Controller.toggle('head'); }
    });
    var filters = app.createFilters(api, keepInView, onFilterChange);

    this.create = function () {
      root.append(controls, movies.section, series.section);
      pageScroll.append(root);
      renderControls();
      loadRail(movies, true);
      loadRail(series, true);
      return this.render();
    };
    this.render = function () { return pageScroll.render(); };
    this.start = function () {
      Lampa.Controller.add('content', {
        toggle: updateCollection,
        up: function () { navigation.move(-1); },
        down: function () { navigation.move(1); },
        left: function () {
          if (Navigator.canmove('left')) Navigator.move('left');
          else Lampa.Controller.toggle('menu');
        },
        right: function () {
          if (Navigator.canmove('right')) Navigator.move('right');
        },
        back: self.back
      });
      if (Lampa.Platform && Lampa.Platform.screen && Lampa.Platform.screen('tv') && Lampa.Keypad && Lampa.Keypad.listener) {
        Lampa.Keypad.listener.follow('keydown', onTvKeydown);
      }
      Lampa.Controller.toggle('content');
    };
    this.back = function () { Lampa.Activity.backward(); };
    this.pause = function () {};
    this.stop = function () {};
    this.destroy = function () {
      destroyed = true;
      if (Lampa.Keypad && Lampa.Keypad.listener) Lampa.Keypad.listener.remove('keydown', onTvKeydown);
      pageScroll.destroy();
      movies.scroll.destroy();
      series.scroll.destroy();
    };

    function onFilterChange(action) {
      renderControls();
      if (action) {
        navigation.set(0);
        loadAll(true, action === 'reset');
      }
    }

    function renderControls() {
      controls.empty().append(filters.createButton());
    }

    function updateCollection() {
      var active = Lampa.Controller.enabled && Lampa.Controller.enabled();
      if (!active || active.name !== 'content') return;

      var row = navigation.row();
      var container = row ? row.collection() : controls;
      if (!container.find('.selector').length) container = controls;
      Lampa.Controller.collectionSet(container);
      var preferred = row && row.lastFocus ? row.lastFocus : lastFocus;
      var focus = preferred && container[0].contains(preferred) ? preferred : false;
      Lampa.Controller.collectionFocus(focus, container);
    }

    function onTvKeydown(input) {
      var active = Lampa.Controller.enabled && Lampa.Controller.enabled();
      if (destroyed || !input || input.enabled === false || !active || active.name !== 'content') return;

      var direction = ({ 19: 'up', 20: 'down', 21: 'left', 22: 'right' })[Number(input.code)];
      if (!direction) return;

      if (input.event && input.event.preventDefault) input.event.preventDefault();
      Lampa.Controller.move(direction);
    }

    function createRail(type, title) {
      var rail = {
        type: type,
        lastFocus: null,
        page: 1,
        version: 0,
        hasMore: false,
        loading: false,
        section: $('<section class="russian-cinema-rail"></section>'),
        status: $('<div class="russian-cinema-rail-status"></div>'),
        cards: $('<div class="russian-cinema-list"></div>'),
        scroll: new Lampa.Scroll({ horizontal: true, step: 300, mask: true, over: true })
      };
      var heading = $('<div class="russian-cinema-rail-title"></div>').text(title);
      rail.scroll.append(rail.cards);
      rail.section.append(heading, rail.status, rail.scroll.render());
      rail.collection = function () { return rail.scroll.render(); };
      return rail;
    }

    function keepInView(element, rail) {
      element.on('hover:focus', function () {
        lastFocus = this;
        if (rail) rail.lastFocus = this;
        else if (element.closest('.russian-cinema-controls').length) navigation.set(0);
        if (rail) {
          rail.scroll.update(this);
          if ($(this).hasClass('russian-cinema-item')) {
            var items = rail.cards.find('.russian-cinema-item');
            var index = items.index(this);
            if (rail.hasMore && !rail.loading && index >= Math.max(0, items.length - 8)) {
              loadRail(rail, false);
            }
          }
        }
        pageScroll.update(rail ? rail.section[0] : this);
      });
      return element;
    }

    function loadAll(reset, force) {
      loadRail(movies, reset, force);
      loadRail(series, reset, force);
    }

    function loadRail(rail, reset, force) {
      if (rail.loading && !reset) return;
      if (reset) {
        rail.version += 1;
        rail.page = 1;
        rail.hasMore = false;
        rail.cards.empty();
        var activeController = Lampa.Controller.enabled && Lampa.Controller.enabled();
        if (activeController && activeController.name === 'content') updateCollection();
      }
      rail.loading = true;
      rail.status.text('Загружаю…');
      scanPages(rail, rail.version, force, 0, 0);
    }

    function scanPages(rail, version, force, pagesScanned, found) {
      if (version !== rail.version || destroyed) return;
      var requestedPage = rail.page;
      Promise.resolve(api.getPage(rail.type, requestedPage, filters.state, force)).then(function (data) {
        if (version !== rail.version || destroyed) return;
        data.items.forEach(function (item) { renderItem(rail, item); });
        found += data.items.length;
        rail.page = requestedPage + 1;
        rail.hasMore = data.hasMore;
        if (rail.hasMore && found < pageFillTarget && pagesScanned + 1 < pageLimit) {
          scanPages(rail, version, force, pagesScanned + 1, found);
          return;
        }

        rail.loading = false;
        var total = rail.cards.find('.russian-cinema-item').length;
        if (!total) {
          rail.status.text(filters.state.strictStudios ? 'Нет карточек с российской студией на этих страницах.' : 'Нет карточек с российской страной производства на этих страницах.');
        } else {
          rail.status.empty();
        }
        updateCollection();
      }).catch(function (error) {
        showError(rail, error, version);
      });
    }

    function showError(rail, error, version) {
      if (version !== rail.version) return;
      rail.loading = false;
      if (destroyed) return;
      rail.status.text(error && error.message ? error.message : 'Не удалось загрузить каталог. Проверьте TMDB и API Key.');
      var retry = keepInView($('<div class="russian-cinema-action selector">Повторить</div>'), rail);
      retry.on('hover:enter', function () { loadRail(rail, true, true); });
      rail.cards.append(retry);
      updateCollection();
    }

    function renderItem(rail, item) {
      var title = item.title || item.name || item.original_title || item.original_name || 'Без названия';
      var year = (item.release_date || item.first_air_date || '').slice(0, 4);
      var row = keepInView($('<div class="russian-cinema-item selector"><div class="russian-cinema-poster"><div class="russian-cinema-poster-fallback">Нет постера</div><div class="russian-cinema-rating"></div></div><div class="russian-cinema-title"></div><div class="russian-cinema-meta"></div></div>'), rail);
      if (item.poster_path) {
        var fallbackPaths = (item.poster_fallbacks || []).slice();
        var poster = $('<img class="russian-cinema-poster-image" alt="">');
        function imageUrl(path) {
          var cleanPath = String(path || '').replace(/^\/+/, '');
          return Lampa.TMDB && Lampa.TMDB.image ? Lampa.TMDB.image('t/p/w500/' + cleanPath) : 'https://image.tmdb.org/t/p/w500/' + cleanPath;
        }
        poster.on('load', function () { row.find('.russian-cinema-poster-fallback').remove(); });
        poster.on('error', function () {
          if (Lampa.TMDB && Lampa.TMDB.broken) Lampa.TMDB.broken();
          if (fallbackPaths.length) poster.attr('src', imageUrl(fallbackPaths.shift()));
        });
        poster.attr('src', imageUrl(item.poster_path));
        row.find('.russian-cinema-poster').prepend(poster);
      }
      row.find('.russian-cinema-title').text(title);
      row.find('.russian-cinema-meta').text(year);
      if (item.vote_average) row.find('.russian-cinema-rating').text(Number(item.vote_average).toFixed(1));
      row.on('hover:enter', function () {
        Lampa.Activity.push({
          url: '', title: title, component: 'full', id: item.id,
          method: rail.type, card: item, source: 'tmdb'
        });
      });
      rail.cards.append(row);
    }
  };
})(window);

/* src/plugin.js */
(function (window) {
  'use strict';

  var app = window.RussianCinemaPlugin = window.RussianCinemaPlugin || {};
  var READY = 'plugin_russian_cinema_ready';
  var ICON = '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="4" width="18" height="16" rx="2" stroke="currentColor" stroke-width="1.8"/><path d="M8 4v16M16 4v16M3 9h5m-5 6h5m8-6h5m-5 6h5" stroke="currentColor" stroke-width="1.5"/></svg>';

  function start() {
    if (window[READY] || !window.Lampa) return;
    window[READY] = true;

    Lampa.SettingsApi.addComponent({
      component: 'russian_cinema',
      name: 'Российское кино',
      icon: ICON
    });
    Lampa.SettingsApi.addParam({
      component: 'russian_cinema',
      param: { name: 'russian_cinema_tmdb_key', type: 'input', default: '', values: '', placeholder: 'TMDB API Key v3' },
      field: { name: 'TMDB API Key v3', description: 'Ключ v3 из настроек TMDB. Нужен, если встроенный ключ этой версии Lampa отклоняется. Сохраняется локально в настройках Lampa.' }
    });

    Lampa.Component.add('russian_cinema_view', app.RussianCinemaView);
    if (Lampa.Head && Lampa.Head.addIcon) {
      Lampa.Head.addIcon(ICON, openCatalog).addClass('russian-cinema-head');
    }
    if (Lampa.Menu && Lampa.Menu.addButton) {
      Lampa.Menu.addButton(ICON, 'Российское кино', openCatalog).addClass('russian-cinema-menu');
    }
  }

  function openCatalog() {
    Lampa.Activity.push({ url: '', title: 'Российское кино', component: 'russian_cinema_view' });
  }

  function bootstrap() {
    if (!window.Lampa) {
      setTimeout(bootstrap, 100);
      return;
    }
    if (window.appready) {
      start();
      return;
    }
    if (Lampa.Listener && Lampa.Listener.follow) {
      Lampa.Listener.follow('app', function (event) {
        if (event.type === 'ready') start();
      });
      return;
    }
    setTimeout(bootstrap, 100);
  }

  app.addStyles();
  bootstrap();
})(window);
